import React from "react";
import { Routes, Route } from "react-router-dom"; // Remova o BrowserRouter daqui
import Navbar from "./components/Navbar/Navbar";
import Carousel from "./components/Carousel/Carousel";
import Sidebar from "./components/Sidebar/Sidebar";
import Home from "./components/Home/Home";
import ProductList from "./components/ProductList/ProductList"; // Importe o componente
import Footer from "./components/Footer/Footer";
import "./App.css";

function App() {
  return (
    <div className="App">
      <Navbar />
      <Carousel />
      <div className="main-content">
        <Routes>
          <Route path="/" element={<Home />} /> {/* Rota para a página inicial */}
          <Route path="/novidades" element={<ProductList />} /> {/* Rota para a lista de produtos */}
        </Routes>
        <Sidebar />
      </div>
      <Footer />
    </div>
  );
}

export default App;
